// workoutLikeWhereR holds the relationship-based filters of
// workoutLikeWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type workoutLikeWhereR[Q psql.Filterable] struct {
	cols workoutLikeColumns
}

// HasUser filters parents that have a matching User using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Users).
func (w workoutLikeWhereR[Q]) HasUser(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Users.NameExpr()),
		sm.Where(Users.Columns.ID.EQ(w.cols.UserID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasWorkout filters parents that have a matching Workout using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Workouts).
func (w workoutLikeWhereR[Q]) HasWorkout(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Workouts.NameExpr()),
		sm.Where(Workouts.Columns.ID.EQ(w.cols.WorkoutID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *WorkoutLike) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("workoutLike cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel
		o.R.Loaded.User = true

		if rel != nil {
			rel.R.WorkoutLikes = WorkoutLikeSlice{o}
		}
		return nil
	case "Workout":
		rel, ok := retrieved.(*Workout)
		if !ok {
			return fmt.Errorf("workoutLike cannot load %T as %q", retrieved, name)
		}

		o.R.Workout = rel
		o.R.Loaded.Workout = true

		if rel != nil {
			rel.R.WorkoutLikes = WorkoutLikeSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("workoutLike has no relationship %q", name)
	}
}

type workoutLikePreloader struct {
	User    func(...psql.PreloadOption) psql.Preloader
	Workout func(...psql.PreloadOption) psql.Preloader
}

func buildWorkoutLikePreloader() workoutLikePreloader {
	return workoutLikePreloader{
		User: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*User, UserSlice](psql.PreloadRel{
				Name: "User",
				Sides: []psql.PreloadSide{
					{
						From:        WorkoutLikes,
						To:          Users,
						FromColumns: []string{"user_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Users.Columns.Names(), userScanMapperNullable, opts...)
		},
		Workout: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Workout, WorkoutSlice](psql.PreloadRel{
				Name: "Workout",
				Sides: []psql.PreloadSide{
					{
						From:        WorkoutLikes,
						To:          Workouts,
						FromColumns: []string{"workout_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Workouts.Columns.Names(), workoutScanMapperNullable, opts...)
		},
	}
}

type workoutLikeThenLoader[Q orm.Loadable] struct {
	User    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Workout func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildWorkoutLikeThenLoader[Q orm.Loadable]() workoutLikeThenLoader[Q] {
	type UserLoadInterface interface {
		LoadUser(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type WorkoutLoadInterface interface {
		LoadWorkout(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return workoutLikeThenLoader[Q]{
		User: thenLoadBuilder[Q](
			"User",
			func(ctx context.Context, exec bob.Executor, retrieved UserLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadUser(ctx, exec, mods...)
			},
		),
		Workout: thenLoadBuilder[Q](
			"Workout",
			func(ctx context.Context, exec bob.Executor, retrieved WorkoutLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadWorkout(ctx, exec, mods...)
			},
		),
	}
}

// LoadUser loads the workoutLike's User into the .R struct
func (o *WorkoutLike) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.User = nil
	o.R.Loaded.User = false

	related, err := o.User(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.WorkoutLikes = WorkoutLikeSlice{o}

	o.R.User = related
	o.R.Loaded.User = true
	return nil
}

// LoadUser loads the workoutLike's User into the .R struct
func (os WorkoutLikeSlice) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.User(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.User = nil
		o.R.Loaded.User = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	workoutLikeByKey := make(map[uuid.UUID][]*WorkoutLike, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		workoutLikeByKey[o.UserID] = append(workoutLikeByKey[o.UserID], o)
	}

	for _, rel := range users {

		owners, ok := workoutLikeByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.User != nil {
				continue
			}

			rel.R.WorkoutLikes = append(rel.R.WorkoutLikes, o)

			o.R.User = rel

		}
	}

	return nil
}

