type workoutLikeJoins[Q dialect.Joinable] struct {
	typ     string
	User    modAs[Q, userColumns]
	Workout modAs[Q, workoutColumns]
}

func (j workoutLikeJoins[Q]) aliasedAs(alias string) workoutLikeJoins[Q] {
	return buildWorkoutLikeJoins[Q](buildWorkoutLikeColumns(alias), j.typ)
}

func buildWorkoutLikeJoins[Q dialect.Joinable](cols workoutLikeColumns, typ string) workoutLikeJoins[Q] {
	return workoutLikeJoins[Q]{
		typ: typ,
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
		Workout: modAs[Q, workoutColumns]{
			c: Workouts.Columns,
			f: func(to workoutColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Workouts.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.WorkoutID),
					))
				}

				return mods
			},
		},
	}
}
